create table public.mobile_account_deletions (user_id uuid primary key, receipt_hash text not null unique check (receipt_hash ~ '^[a-f0-9]{64}$'), status text not null default 'deleting' check (status in ('deleting','complete'))); alter table public.mobile_account_deletions enable row level security; revoke all on public.mobile_account_deletions from public,anon,authenticated; grant select,insert,update on public.mobile_account_deletions to service_role; create schema if not exists private; create or replace function private.fence_deleted_mobile_account() returns trigger language plpgsql security definer set search_path='' as $$ declare owner_uuid uuid; begin if TG_TABLE_SCHEMA='storage' then if NEW.bucket_id <> 'resume-files' then return NEW; end if; begin owner_uuid := split_part(NEW.name,'/',1)::uuid; exception when invalid_text_representation then return NEW; end; elsif TG_TABLE_NAME='profiles' then owner_uuid := NEW.id; else owner_uuid := NEW.user_id; end if; perform pg_advisory_xact_lock(hashtextextended(owner_uuid::text, 4024)); if exists(select 1 from public.mobile_account_deletions where user_id=owner_uuid) then raise exception 'Account deletion in progress' using errcode='42501'; end if; return NEW; end; $$; revoke all on function private.fence_deleted_mobile_account() from public,anon,authenticated; create trigger mobile_deletion_fence before insert or update on public.user_resumes for each row execute function private.fence_deleted_mobile_account(); create trigger mobile_deletion_fence before insert or update on public.user_tailored_cvs for each row execute function private.fence_deleted_mobile_account(); create trigger mobile_deletion_fence before insert or update on public.user_tailoring_progress for each row execute function private.fence_deleted_mobile_account(); create trigger mobile_deletion_fence before insert or update on public.mobile_ai_consent for each row execute function private.fence_deleted_mobile_account(); create trigger mobile_deletion_fence before insert or update on public.profiles for each row execute function private.fence_deleted_mobile_account(); create trigger mobile_deletion_fence before insert or update on storage.objects for each row execute function private.fence_deleted_mobile_account(); create or replace function private.serialize_mobile_deletion() returns trigger language plpgsql set search_path='' as $$ begin perform pg_advisory_xact_lock(hashtextextended(NEW.user_id::text,4024)); return NEW; end; $$; revoke all on function private.serialize_mobile_deletion() from public,anon,authenticated; create trigger serialize_mobile_deletion before insert on public.mobile_account_deletions for each row execute function private.serialize_mobile_deletion();

